{
  "passageId": "modern-civilization-science-na",
  "items": [
    {
      "id": "R1",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "서양 과학과 기술에 대한 관심이 의욕적인 기술 수용이라는 구체적 모습으로 나타났음을 설명한다."
    },
    {
      "id": "R2",
      "type": "PARALLEL",
      "otherName": "",
      "reason": "근대화 추진과 서양 기술 수용을 같은 시기에 함께 진행된 활동으로 나란히 제시한다."
    },
    {
      "id": "R3",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "적극적으로 기술을 수용했지만 그것만으로는 충분하지 않았다는 한계를 제시한다."
    },
    {
      "id": "R4",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "청일 전쟁 패배와 기술 수용의 한계 인식이 과학 정신의 사회적 이식 시도가 등장한 역사적 계기로 제시된다."
    },
    {
      "id": "R5",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "기술 수용의 한계를 깨닫고 과학 정신을 추구하게 된 역사적 상황이 옌푸의 주장이 등장하는 배경을 이룬다."
    },
    {
      "id": "R6",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "국가 간 약육강식의 경쟁이라는 현실을 근거로 승리를 위해 기술과 정신적 자질이 필요하다는 주장을 제시한다."
    },
    {
      "id": "R7",
      "type": "PARALLEL",
      "otherName": "",
      "reason": "기술과 국민의 정신적 자질을 경쟁에서 승리하기 위해 함께 필요한 두 요소로 나란히 제시한다."
    },
    {
      "id": "R8",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "필요한 정신적 자질을 과학적 사유 능력이라는 핵심 내용으로 구체화한다."
    },
    {
      "id": "R9",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "과학적 사유 능력을 가장 중시하는 판단이 정치적 변혁에도 과학 정신이 전제되어야 한다는 주장을 뒷받침한다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "과학을 인과 실증에 근거한 근대 학문으로 파악한 것이 과학 습득으로 전통 학문의 폐단을 극복해야 한다는 주장의 토대가 된다."
    },
    {
      "id": "R11",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "옌푸의 입장이 천두슈에게 계승되었다는 설명을 천두슈와 신문화 운동의 구체적인 주장들로 풀어 제시한다."
    },
    {
      "id": "R12",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "옌푸와 천두슈 모두 과학 정신을 정치적 변혁과 민주 정치 실현의 필수 토대로 본다."
    },
    {
      "id": "R13",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "과학을 통해 전통의 폐단을 극복하려는 옌푸의 입장을 신문화 운동의 지식인들이 이어받는다."
    },
    {
      "id": "R14",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "과학에 근거한 신문화를 이루려는 목적을 위해 전통문화에 대한 부정과 비판을 수단으로 삼는다."
    },
    {
      "id": "R15",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "사상과 철학에 과학적 방법이 필요하다는 원칙을 사회와 인간의 삶에 대한 연구 영역에도 적용한다."
    },
    {
      "id": "R16",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "과학을 이용한 죄악은 인정하면서도 그 책임을 과학 자체의 죄악으로까지 확대할 수는 없다고 한정한다."
    },
    {
      "id": "R17",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "전쟁의 비극이 과학 자체의 죄악은 아니라는 판단이 기존의 과학 옹호 입장을 유지하는 근거가 된다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "전후 유럽 시찰 경험을 그 과정에서 목도한 과학의 역작용이라는 구체적 내용으로 설명한다."
    },
    {
      "id": "R19",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "통제되지 않은 과학의 역작용을 목도한 경험이 서양 근대 문명 비판의 계기로 제시된다."
    },
    {
      "id": "R20",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "과학의 발달로도 인생관의 문제를 해결할 수 없다는 판단을 들어 서양 근대 문명에 대한 비판을 뒷받침한다."
    },
    {
      "id": "R21",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "과학적 방법 자체는 인정하지만 인생관의 문제에까지 적용할 수는 없다고 한계를 설정한다."
    },
    {
      "id": "R22",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "인생관이 과학과 별개의 영역이라는 판단이 인생관에 과학적 방법을 적용할 수 없다는 주장을 뒷받침한다."
    },
    {
      "id": "R23",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "중국 전통 가치관을 부정한 신문화 운동과 이를 수호하려는 장쥔마이의 상반된 입장을 제시한다."
    },
    {
      "id": "R24",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "인간의 삶에 대한 과학적 방법의 적용을 요구하는 천두슈와 인생관에는 적용할 수 없다는 장쥔마이의 견해가 다르다."
    },
    {
      "id": "R25",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "전통문화의 부정과 비판을 추구한 신문화 운동과 전통 가치관의 수호를 내세운 장쥔마이의 입장을 비교한다."
    },
    {
      "id": "R26",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "세계 대전 이후에도 과학 옹호를 유지한 천두슈와 과학의 한계를 지적하며 근대 문명을 비판한 장쥔마이의 견해를 대비한다."
    },
    {
      "id": "R27",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "과학을 정치·문화·인간 연구의 토대로 삼는 입장과 과학의 적용 범위를 제한하고 전통 가치를 수호하는 입장이 대비된다."
    }
  ]
}

